// ---- object Turret — one definition, a generated family per target (SPEC §4.8) ----

// TurretState — the full simulation struct: every field
type TurretState struct {
	Parent      Handle
	TurretIndex int32 // wire [0, 255]
	Rotation    Quat
	Flags       uint64
	Team        Team // [local] — no wire
}

// TurretData_Deep — every non-[local] field, deep encodings: full state for
// client-side prediction
type TurretData_Deep struct {
	Parent      Handle
	TurretIndex int32 // wire [0, 255]
	Rotation    Quat
	Flags       uint64
}

// TurretData_Shallow — the [interpolate] fields on the quantized wire: the
// implementation detail on the way to interpolation on the client
type TurretData_Shallow struct {
	Parent      Handle
	TurretIndex int32 // wire [0, 255]
	// rotation: Quat quantized by RotationUnits, max 1 — per-component int in [-1024, 1024]
	RotationX int16
	RotationY int16
	RotationZ int16
	RotationW int16
	Flags     uint64
}

// TurretData_Interpolate — the same fields in interpolate storage: projected
// fields stay in the wire integer domain and snap-interpolate; quantized
// composites store continuous (SPEC §4.8 rule 5)
type TurretData_Interpolate struct {
	Parent      Handle
	TurretIndex int32 // wire [0, 255]
	Rotation    Quat
	Flags       uint64
}

const TurretData_DeepMaxBits = 350
const TurretData_DeepMaxBytes = 48 // rounded up to the 8-byte write-buffer granularity

func WriteTurretData_Deep(stream *serialize.WriteStream, value *TurretData_Deep) error {
	if err := WriteHandle(stream, &value.Parent); err != nil {
		return err
	}
	if value.TurretIndex < 0 || value.TurretIndex > MaxTurretsPerShip-1 { // the runtime range refusal, folded (SPEC §5)
		return serialize.ErrValueOutOfRange
	}
	{
		offsetValue := uint32(value.TurretIndex)
		stream.SerializeBits(&offsetValue, 8)
	}
	if err := WriteQuat(stream, &value.Rotation); err != nil {
		return err
	}
	stream.SerializeBits64(&value.Flags, 64)
	return stream.Err()
}

func ReadTurretData_Deep(stream *serialize.ReadStream, value *TurretData_Deep) error {
	if err := ReadHandle(stream, &value.Parent); err != nil {
		return err
	}
	stream.SerializeInt(&value.TurretIndex, 0, MaxTurretsPerShip-1)
	if err := ReadQuat(stream, &value.Rotation); err != nil {
		return err
	}
	stream.SerializeBits64(&value.Flags, 64)
	return stream.Err()
}

